{"results": [{"id": "hp_doc_7e43c8687965ac20f31a912c10bee6d9826ddaa4bf14ef7ac9e5e6c4eab5c13a", "title": "Phoenix Suns", "text": "The Phoenix Suns are an American professional basketball team based in Phoenix, Arizona. The Suns compete in the National Basketball Association (NBA) as a member team of the league's Western Conference Pacific Division, and are the only team in their division not to be based in California. Since 1992, the Suns have played their home games at Talking Stick Resort Arena in downtown Phoenix.", "score": 33.5282}, {"id": "hp_doc_0161af236a46443adeb8e894479720fbbf9c8a3fac0e6942d9e60d9fee55573c", "title": "1971–72 Phoenix Suns season", "text": "The 1971–72 Phoenix Suns season was the fourth season for the Phoenix Suns of the National Basketball Association. With a 49–33 record, the Suns hold the NBA record as the team with the best winning percentage to not make the playoffs. The team broke the record they set the previous year with a 48–34 finish. Head coach Cotton Fitzsimmons led the Suns in their debut season as members of the Pacific division. All home games were played at Arizona Veterans Memorial Coliseum.", "score": 26.3601}, {"id": "hp_doc_9c13bb0156f5b93e9d530ffe3e5c3666ea291c7960d3a5316d034d2147dd00de", "title": "2016–17 Phoenix Suns season", "text": "The 2016–17 NBA season was the Suns' 49th season in the NBA. It is also their 24th season in the Talking Stick Resort Arena. It is also the first season with a team-owned D-League affiliate, called the Northern Arizona Suns, which recently relocated to the nearby Prescott Valley. The Suns failed to qualify for the playoffs for the seventh straight season.", "score": 21.9467}], "remaining_searches": 1}
